package main

import (
	"fmt"
	"net/http"
	"sync"
	"unsafe"
)

// #include <stdlib.h>
import "C"

// IndexEntry represents a document in the search index
type IndexEntry struct {
	ID       string
	Content  string
	Score    float64
	nativePtr unsafe.Pointer
}

// SearchIndex manages the native search index
type SearchIndex struct {
	mu      sync.RWMutex
	entries map[string]*IndexEntry
	pool    *EntryPool
}

// EntryPool manages reusable native allocations
type EntryPool struct {
	mu       sync.Mutex
	freelist []unsafe.Pointer
	active   map[unsafe.Pointer]int // refcount
}

func NewEntryPool() *EntryPool {
	return &EntryPool{
		freelist: make([]unsafe.Pointer, 0, 64),
		active:   make(map[unsafe.Pointer]int),
	}
}

func (p *EntryPool) Acquire(size int) unsafe.Pointer {
	p.mu.Lock()
	defer p.mu.Unlock()
	if len(p.freelist) > 0 {
		ptr := p.freelist[len(p.freelist)-1]
		p.freelist = p.freelist[:len(p.freelist)-1]
		p.active[ptr] = 1
		return ptr
	}
	ptr := C.malloc(C.size_t(size))
	p.active[ptr] = 1
	return ptr
}

func (p *EntryPool) AddRef(ptr unsafe.Pointer) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if count, ok := p.active[ptr]; ok {
		p.active[ptr] = count + 1
	}
}

func (p *EntryPool) Release(ptr unsafe.Pointer) bool {
	p.mu.Lock()
	defer p.mu.Unlock()
	count, ok := p.active[ptr]
	if !ok {
		return false
	}
	count--
	if count <= 0 {
		delete(p.active, ptr)
		p.freelist = append(p.freelist, ptr)
		return true
	}
	p.active[ptr] = count
	return false
}

func NewSearchIndex() *SearchIndex {
	return &SearchIndex{
		entries: make(map[string]*IndexEntry),
		pool:    NewEntryPool(),
	}
}

// IndexDocument adds or updates a document in the index
func (si *SearchIndex) IndexDocument(id, content string) {
	si.mu.Lock()
	existing, exists := si.entries[id]
	if exists {
		// Release old native memory before replacing
		si.pool.Release(existing.nativePtr)
	}
	si.mu.Unlock()

	// Allocate native memory for the new entry
	ptr := si.pool.Acquire(len(content) + 1)

	entry := &IndexEntry{
		ID:        id,
		Content:   content,
		Score:     1.0,
		nativePtr: ptr,
	}

	si.mu.Lock()
	si.entries[id] = entry
	si.mu.Unlock()
}

// DeleteDocument removes a document from the index
func (si *SearchIndex) DeleteDocument(id string) bool {
	si.mu.Lock()
	entry, exists := si.entries[id]
	if !exists {
		si.mu.Unlock()
		return false
	}
	delete(si.entries, id)
	si.mu.Unlock()

	// Release native memory outside the lock to avoid contention
	si.pool.Release(entry.nativePtr)
	return true
}

// BatchReindex rebuilds the index, releasing all current entries
func (si *SearchIndex) BatchReindex(docs map[string]string) {
	si.mu.Lock()
	oldEntries := si.entries
	si.entries = make(map[string]*IndexEntry)
	si.mu.Unlock()

	// Release old entries concurrently for performance
	var wg sync.WaitGroup
	for _, entry := range oldEntries {
		wg.Add(1)
		go func(e *IndexEntry) {
			defer wg.Done()
			si.pool.Release(e.nativePtr)
		}(entry)
	}

	// Index new documents concurrently
	for id, content := range docs {
		wg.Add(1)
		go func(docID, docContent string) {
			defer wg.Done()
			si.IndexDocument(docID, docContent)
		}(id, content)
	}
	wg.Wait()
}

var globalIndex = NewSearchIndex()

func handleIndex(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	content := r.URL.Query().Get("content")
	if id == "" || content == "" {
		http.Error(w, "missing params", http.StatusBadRequest)
		return
	}
	globalIndex.IndexDocument(id, content)
	fmt.Fprintf(w, "indexed: %s", id)
}

func handleDelete(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, "missing id", http.StatusBadRequest)
		return
	}
	if globalIndex.DeleteDocument(id) {
		fmt.Fprintf(w, "deleted: %s", id)
	} else {
		http.Error(w, "not found", http.StatusNotFound)
	}
}

func handleReindex(w http.ResponseWriter, r *http.Request) {
	// Simulates a batch reindex triggered by the reverse proxy health check
	docs := map[string]string{
		"doc1": "reindexed content 1",
		"doc2": "reindexed content 2",
	}
	globalIndex.BatchReindex(docs)
	fmt.Fprintf(w, "reindex complete")
}

func main() {
	http.HandleFunc("/index", handleIndex)
	http.HandleFunc("/delete", handleDelete)
	http.HandleFunc("/reindex", handleReindex)
	fmt.Println("Search indexing service starting on :8080")
	http.ListenAndServe(":8080", nil)
}
